export function MarketValueCalculatorPage(){
 const {user}=useAuth(); const {salary,contribution,stability,rarity,step,started,set,next,back,reset}=useCalc();
 const [lang,setLang]=useState<Lang>(()=>(localStorage.getItem('incore-lang') as Lang)||'ru');
 const [showAuth,setShowAuth]=useState(false); const [authMode,setAuthMode]=useState<'register'|'login'>('register'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [authError,setAuthError]=useState(''); const [authMessage,setAuthMessage]=useState(''); const [saving,setSaving]=useState(false); const [saved,setSaved]=useState(false); const [modal,setModal]=useState(false); const [gap,setGap]=useState<Gap|null>(null); const [role,setRole]=useState(''); const [outcome,setOutcome]=useState(''); const [problem,setProblem]=useState(''); const [problemLoss,setProblemLoss]=useState(0); const [evidence,setEvidence]=useState<boolean[]>([false,false,false,false,false]); const [skills,setSkills]=useState<Skill[]>([{name:'',level:5,criticality:5,evidence:''}]); const resultRef=useRef<HTMLDivElement|null>(null); const t=base[lang];
 useEffect(()=>{localStorage.setItem('incore-lang',lang);document.documentElement.lang=lang;},[lang]);
 useEffect(()=>{try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);set({salary:v.salary,contribution:v.contribution,stability:v.stability,rarity:v.rarity});if(typeof v.problem==='string')setProblem(v.problem);if(typeof v.problemLoss==='number')setProblemLoss(v.problemLoss);if(Array.isArray(v.evidence))setEvidence(v.evidence.map(Boolean).slice(0,5).concat([false,false,false,false,false]).slice(0,5));}}catch{}},[set]);
 useEffect(()=>{localStorage.setItem(KEY,JSON.stringify({salary,contribution,stability,rarity,problem,problemLoss,evidence}));},[salary,contribution,stability,rarity,problem,problemLoss,evidence]);
 const metrics=useMemo(()=>{const full=fullCost(salary);const cap=capacity(contribution,stability,rarity);const r=ratio(full,cap);const verdict:'low'|'mid'|'high'=r<0.7?'low':r<=1.2?'mid':'high';const evidenceScore=Math.round((evidence.filter(Boolean).length/evidence.length)*100);const problemCoverage=problemLoss>0?Math.min(100,Math.round((contribution/problemLoss)*100)):null;const gapToNextLevel=Math.max(0,cap-full);return{full,cap,ratio:r,verdict,gap:cap-full,evidenceScore,problemCoverage,gapToNextLevel};},[salary,contribution,stability,rarity,evidence,problemLoss]);
 const fire=(name:string)=>window.dispatchEvent(new CustomEvent('incore:analytics',{detail:{name}}));
 const begin=()=>{fire(t.analyticsStarted);if(user)next();else setShowAuth(true);};
 const submitAuth=async()=>{setAuthError('');setAuthMessage('');if(!email||password.length<6){setAuthError(t.authError);return;}setSaving(true);try{if(authMode==='register'){const {data,error}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{source:'market-value-calculator'}}});if(error)throw error;if(!data.session){setAuthMessage(t.confirm);return;}}else{const{error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;}setShowAuth(false);next();}catch(e:any){setAuthError(e?.message||t.authError);}finally{setSaving(false);}};
 const saveResult=async()=>{if(!user){setShowAuth(true);return;}setSaving(true);try{const{error}=await supabase.from('b2c_market_value_calculations').insert({user_id:user.id,net_salary:salary,economic_contribution:contribution,stability,rarity,full_cost:metrics.full,capacity:metrics.cap,ratio:metrics.ratio,verdict:metrics.verdict});if(error)throw error;setSaved(true);fire(t.analyticsCompleted);}catch(e:any){setAuthError(e?.message||t.saveError);}finally{setSaving(false);}};
 const downloadPdf=async()=>{if(!resultRef.current)return;setSaving(true);let hidden:HTMLElement[]=[];let pdfValues:HTMLElement[]=[];let inputs:HTMLInputElement[]=[];try{const el=resultRef.current;hidden=Array.from(el.querySelectorAll<HTMLElement>('[data-pdf-exclude]'));hidden.forEach(x=>{x.dataset.pdfDisplay=x.style.display;x.style.display='none';});pdfValues=Array.from(el.querySelectorAll<HTMLElement>('[data-pdf-value]'));pdfValues.forEach(x=>x.style.display='block');inputs=Array.from(el.querySelectorAll<HTMLInputElement>('[data-pdf-input]'));inputs.forEach(x=>x.style.display='none');await document.fonts?.ready;const canvas=await html2canvas(el,{scale:2,backgroundColor:null,useCORS:true,logging:false,windowWidth:el.scrollWidth,windowHeight:el.scrollHeight,scrollX:0,scrollY:-window.scrollY});const pdf=new jsPDF('p','mm','a4');const pageWidth=210,pageHeight=297,margin=10,usableWidth=pageWidth-margin*2,usableHeight=pageHeight-margin*2,pxPerPage=Math.max(1,Math.floor(canvas.width*usableHeight/usableWidth));let sourceY=0,pageIndex=0;while(sourceY<canvas.height){const sliceHeightPx=Math.min(pxPerPage,canvas.height-sourceY);const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=sliceHeightPx;const ctx=slice.getContext('2d');if(!ctx)throw new Error('Canvas context unavailable');ctx.fillStyle='#f8fafc';ctx.fillRect(0,0,slice.width,slice.height);ctx.drawImage(canvas,0,sourceY,canvas.width,sliceHeightPx,0,0,slice.width,slice.height);if(pageIndex>0)pdf.addPage();const renderedHeight=Math.min(usableHeight,sliceHeightPx*usableWidth/slice.width);pdf.addImage(slice,'JPEG',margin,margin,usableWidth,renderedHeight,undefined,'FAST');sourceY+=sliceHeightPx;pageIndex++;}pdf.save('incore-market-value.pdf');fire(t.analyticsPdf);}catch(e:any){setAuthError(e?.message||t.saveError);}finally{hidden.forEach(x=>x.style.display=x.dataset.pdfDisplay||'');pdfValues.forEach(x=>x.style.display='none');inputs.forEach(x=>x.style.display='');setSaving(false);}}; const share=async()=>{const text=`${t.power}: ${money(metrics.cap,lang)}. ${t.ratioTitle}: ${metrics.ratio.toFixed(2)}`;if(navigator.share)await navigator.share({title:t.resultTitle,text});else await navigator.clipboard?.writeText(text);}; const updateSkill=(i:number,p:Partial<Skill>)=>setSkills(s=>s.map((x,idx)=>idx===i?{...x,...p}:x)); const completedSkills=skills.filter(s=>s.name.trim()); const bottleneck=completedSkills.length>=5?completedSkills.map(s=>({...s,priority:s.level*s.criticality})).filter(s=>s.priority>=50&&s.level<7).sort((a,b)=>b.priority-a.priority)[0]:undefined;
 const pageShell = "hr-calculator market-value-calculator min-h-screen text-slate-900";
 const container = "mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-8";
 const header = <header className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-5 flex items-center"><img src="/logo.png" alt={t.brand} className="h-10 w-auto object-contain"/></div><div className="flex flex-wrap items-center gap-3"><div className="inline-flex rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold uppercase tracking-wide text-indigo-700">РЫНОЧНАЯ СТОИМОСТЬ</div><LanguageSwitch lang={lang} setLang={setLang}/></div><h1 className="mt-3 max-w-3xl text-3xl font-black tracking-tight sm:text-5xl">{step===5?t.resultTitle:t.title}</h1><p className="mt-3 max-w-2xl text-base leading-7 text-slate-600 sm:text-lg">{step===5?t.sub:'Рассчитай стоимость создаваемого результата по четырём параметрам: зарплата, экономический вклад, стабильность и редкость навыка.'}</p></div><button onClick={reset} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-100">{step===5?t.recalc:'Сбросить'}</button></header>;

 if(!started&&step===0)return <main className={pageShell} ><div className={container}>{header}<section className="grid gap-6 lg:grid-cols-[1fr_1.05fr]"><div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="text-sm font-semibold text-slate-800">Как проходит расчёт</div><p className="mt-2 text-sm leading-6 text-slate-500"></p><div className="mt-6 space-y-3">{t.steps.map((label:string,i:number)=><div key={label} className="flex items-center gap-3 rounded-2xl bg-slate-50 p-4"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-white text-sm font-black text-slate-700 shadow-sm">{i+1}</div><div><div className="text-sm font-bold text-slate-900">{label}</div><div className="mt-0.5 text-xs text-slate-500">{i===0?'База расчёта':i===1?'Деньги, которые создаёт работа':i===2?'Предсказуемость результата':'Редкость и AI-устойчивость'}</div></div></div>)}</div><button onClick={begin} className="mt-6 w-full rounded-xl bg-indigo-600 px-6 py-3.5 font-bold text-white shadow-lg shadow-indigo-200 transition hover:bg-indigo-700">{t.start}</button></div><div className="rounded-3xl bg-slate-950 p-6 text-white shadow-xl sm:p-8"><div className="text-sm font-semibold text-slate-300">Что получится в итоге</div><div className="mt-3 text-4xl font-black tracking-tight sm:text-5xl">4 показателя</div><p className="mt-2 text-sm leading-6 text-slate-400">Расчёт покажет рыночную мощность, отношение полной стоимости к этой мощности, экономический разрыв и следующий практический шаг.</p><div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">Фокус</div><div className="mt-1 font-bold">Результат</div></div><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">Формат</div><div className="mt-1 font-bold">PDF-отчёт</div></div></div></div></section>{showAuth&&<AuthModal t={t} authMode={authMode} setAuthMode={setAuthMode} email={email} setEmail={setEmail} password={password} setPassword={setPassword} authError={authError} authMessage={authMessage} submitAuth={submitAuth} saving={saving} close={()=>setShowAuth(false)}/>}</div></main>;

 if(step===5)return <main className={pageShell} style={{ backgroundColor: "#f8fafc" }}><div className={container}>{header}<div ref={resultRef}>
   <section className="grid gap-6 lg:grid-cols-[1fr_1.05fr]">
     <div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7" data-pdf-section>
       <div className="flex items-center justify-between gap-3"><div><div className="text-sm font-semibold text-slate-800">{t.inputs}</div><div className="mt-1 text-xs text-slate-500">Данные, на которых построен расчёт</div></div><div className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">4 / 4</div></div>
       <div className="mt-5 grid gap-3 sm:grid-cols-2"><InputItem label={t.salaryInput} value={money(salary,lang)}/><InputItem label={t.contributionInput} value={money(contribution,lang)}/><InputItem label={t.stabilityInput} value={stability.toFixed(1)}/><InputItem label={t.rarityInput} value={rarity.toFixed(1)}/><InputItem label={t.company} value={money(metrics.full,lang)}/><InputItem label={t.power} value={money(metrics.cap,lang)}/></div>
       <div className="mt-5 rounded-2xl bg-slate-50 p-4"><div className="text-xs font-semibold tracking-wide text-slate-500">{t.gap}</div><div className="mt-1 text-2xl font-black">{metrics.gap>=0?'+':''}{money(metrics.gap,lang)}</div><div className="mt-1 text-xs leading-5 text-slate-500">{t.ratioHint.replace('{ratio}',metrics.ratio.toFixed(2)).replace('{percent}',(metrics.ratio*100).toFixed(0))}</div></div>
     </div>
     <div className="space-y-6">
       <div className="overflow-hidden rounded-3xl bg-slate-950 p-6 text-white shadow-xl sm:p-8" data-pdf-section>
         <div className="flex items-center gap-2 text-sm font-semibold text-slate-300"><span className="inline-block h-2 w-2 rounded-full bg-indigo-400"></span>{t.power}</div>
         <div className="mt-3 text-4xl font-black tracking-tight sm:text-5xl">{money(metrics.cap,lang)}</div>
         <div className="mt-2 text-sm text-slate-400">{t.resultTitle}</div>
         <div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">{t.company}</div><div className="mt-1 font-bold">{money(metrics.full,lang)}</div></div><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">{t.ratioTitle}</div><div className="mt-1 font-bold">{metrics.ratio.toFixed(2)}</div></div></div>
       </div>
       <div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7" data-pdf-section>
         <div className="text-sm font-semibold text-slate-800">{t.ratioTitle}</div>
         <div className="mt-2 text-3xl font-black tracking-tight">{(metrics.ratio*100).toFixed(0)}%</div>
         <p className="mt-2 text-sm leading-6 text-slate-500">{t.ratioHint.replace('{ratio}',metrics.ratio.toFixed(2)).replace('{percent}',(metrics.ratio*100).toFixed(0))}</p>
         <div className="mt-5 h-48"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{name:t.salaryBar,value:metrics.full},{name:t.powerBar,value:metrics.cap}]} margin={{top:10,right:10,left:0,bottom:35}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" angle={-12} textAnchor="end" height={50} tick={{fontSize:11}}/><YAxis tickFormatter={v=>`${Math.round(v/1000)}k`} tick={{fontSize:11}}/><Tooltip formatter={v=>money(Number(v),lang)}/><Bar dataKey="value" radius={[8,8,0,0]}/></BarChart></ResponsiveContainer></div>
       </div>
     </div>
   </section>
   <section className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4" data-pdf-section><Metric title={t.power} value={money(metrics.cap,lang)}/><Metric title={t.ratioTitle} value={metrics.ratio.toFixed(2)}/><Metric title={t.gap} value={`${metrics.gap>=0?'+':''}${money(metrics.gap,lang)}`}/><Metric title={t.company} value={money(metrics.full,lang)}/></section>
   <section className="mt-6 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8" data-pdf-section><Verdict t={t} kind={metrics.verdict}/></section>
   <section className="mt-6 rounded-3xl border border-indigo-100 bg-indigo-50 p-6 sm:p-8" data-pdf-section><div className="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div className="max-w-xl"><div className="text-sm font-bold uppercase tracking-wide text-indigo-700">{t.actionLow===t.actionMid&&t.actionLow}</div><h2 className="mt-2 text-2xl font-black">{metrics.verdict==='low'?t.actionLow:metrics.verdict==='mid'?t.actionMid:t.actionHigh}</h2><p className="mt-2 leading-7 text-slate-700">{metrics.verdict==='low'?t.actionLowText:metrics.verdict==='mid'?t.actionMidText:t.actionHighText}</p></div><div className="w-full max-w-md rounded-2xl bg-white p-5 shadow-sm"><div className="text-xs font-semibold tracking-wide text-slate-500">{t.gap}</div><div className="mt-2 text-2xl font-black">{metrics.gap>=0?'+':''}{money(metrics.gap,lang)}</div><div className="mt-1 text-xs leading-5 text-slate-500">{t.power}: {money(metrics.cap,lang)}</div></div></div></section>
   <BookValueSection lang={lang} problem={problem} setProblem={setProblem} problemLoss={problemLoss} setProblemLoss={setProblemLoss} evidence={evidence} setEvidence={setEvidence} contribution={contribution} metrics={metrics}/>
   <Diagnostic t={t} gap={gap} setGap={setGap}/>
   <div data-pdf-exclude><SkillsChecklist t={t} role={role} setRole={setRole} outcome={outcome} setOutcome={setOutcome} skills={skills} updateSkill={updateSkill} addSkill={()=>setSkills(s=>s.length<7?[...s,{name:'',level:5,criticality:5,evidence:''}]:s)} removeSkill={(i:number)=>setSkills(s=>s.length>5?s.filter((_,idx)=>idx!==i):s)} bottleneck={bottleneck}/></div>
 </div><div className="mt-6 flex flex-wrap gap-3"><button onClick={downloadPdf} disabled={saving} className="rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white shadow-lg shadow-indigo-200 transition hover:bg-indigo-700 disabled:opacity-50">{saving?t.saving:t.pdf}</button><button onClick={saveResult} disabled={saving||saved} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-100">{saving?t.saving:saved?t.saved:t.save}</button><button onClick={share} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-100">{t.share}</button>{authError&&<div className="basis-full text-sm text-red-700">{authError}</div>}</div></div></main>;

 return <main className={pageShell}><div className={container}>{header}<section className="grid gap-6 lg:grid-cols-[1fr_1.05fr]"><div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-semibold text-slate-800">{t.steps[Math.max(0,step-1)]||t.steps[0]}</div><div className="mt-1 text-xs text-slate-500">Шаг {step} из 4</div></div><div className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">{step} / 4</div></div><div className="mt-5 flex gap-2" aria-label="Progress">{[1,2,3,4].map(n=><div key={n} className={`h-2 flex-1 rounded-full ${n<=step?'bg-indigo-600':'bg-slate-200'}`}/>)}</div><div className="mt-8">{step===1&&<SalaryStep t={t} value={salary} set={set} lang={lang}/>} {step===2&&<ContributionStep t={t} value={contribution} set={set} openModal={()=>setModal(true)}/>} {step===3&&<SliderStep title={t.stabilityTitle} value={stability} min={0.5} max={1.5} step={0.1} set={(v:number)=>set({stability:v})} low={t.stabilityLow} mid={t.stabilityMid} high={t.stabilityHigh}/>} {step===4&&<SliderStep title={t.rarityTitle} value={rarity} min={0.8} max={2} step={0.1} set={(v:number)=>set({rarity:v})} low={t.rarityLow} mid={t.rarityMid} high={t.rarityHigh}/>}</div><div className="mt-8 flex justify-between gap-3"><button onClick={back} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-100">{t.back}</button><button onClick={next} disabled={step===1?salary<=0:step===2?contribution<=0:false} className="rounded-xl bg-indigo-600 px-6 py-3 font-bold text-white shadow-lg shadow-indigo-200 transition hover:bg-indigo-700 disabled:opacity-40">{t.next}</button></div></div><div className="space-y-6"><div className="overflow-hidden rounded-3xl bg-slate-950 p-6 text-white shadow-xl sm:p-8"><div className="text-sm font-semibold text-slate-300">Текущий расчёт</div><div className="mt-3 text-4xl font-black tracking-tight sm:text-5xl">{step===1?money(fullCost(salary),lang):step===2?money(contribution,lang):step===3?stability.toFixed(1):rarity.toFixed(1)}</div><div className="mt-2 text-sm text-slate-400">{step===1?t.company:step===2?t.contributionTitle:step===3?t.stabilityTitle:t.rarityTitle}</div><div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">Шаг</div><div className="mt-1 font-bold">{step} / 4</div></div><div className="rounded-2xl bg-white/10 p-4"><div className="text-xs text-slate-400">Дальше</div><div className="mt-1 font-bold">{t.next}</div></div></div></div><div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="text-sm font-semibold text-slate-800">Почему это важно</div><p className="mt-2 text-sm leading-6 text-slate-500">Здесь не сравнивается человек со средней зарплатой. Расчёт связывает стоимость для компании с экономическим результатом и его устойчивостью.</p></div></div></section>{modal&&<ExampleModal t={t} close={()=>setModal(false)}/>} {showAuth&&<AuthModal t={t} authMode={authMode} setAuthMode={setAuthMode} email={email} setEmail={setEmail} password={password} setPassword={setPassword} authError={authError} authMessage={authMessage} submitAuth={submitAuth} saving={saving} close={()=>setShowAuth(false)}/>}</div></main>;

}

function BookValueSection({lang,problem,setProblem,problemLoss,setProblemLoss,evidence,setEvidence,contribution,metrics}:{lang:Lang;problem:string;setProblem:(v:string)=>void;problemLoss:number;setProblemLoss:(v:number)=>void;evidence:boolean[];setEvidence:(v:boolean[])=>void;contribution:number;metrics:any}){const ru=lang==='ru';const items=ru?['Результат подтверждён деньгами: выручка, маржа или экономия','Есть измеримое изменение: конверсия, скорость, удержание, качество или объём','Есть сравнение «до / после» или понятная базовая линия','Есть артефакт доказательства: CRM, отчёт, метрика, документ или отзыв','Результат воспроизводится, а не был разовым совпадением']:['The result is tied to money: revenue, margin or savings','There is a measurable change: conversion, speed, retention, quality or volume','There is a clear before/after comparison or baseline','There is evidence: CRM data, report, metric, document or reference','The result is repeatable, not a one-off coincidence'];const checked=evidence.filter(Boolean).length;return <section data-pdf-section className="mt-6 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-7"><h2 className="text-2xl font-bold">{ru?'Что делает твою цену доказуемой':'What makes your value provable'}</h2><p className="mt-2 leading-7 text-slate-600">{ru?'Доказательство отделено от самого результата: рынок снижает риск, когда результат можно проверить. Этот показатель не входит в расчёт рыночной мощности. Это самопроверка качества доказательств.':'Proof is separate from the result. This score does not change the calculation. It is a self-check of how well your value is evidenced.'}</p><div className="mt-5 space-y-2">{items.map((x,i)=><label key={x} className="flex items-start gap-3 rounded-xl border border-slate-200 p-3"><input type="checkbox" checked={!!evidence[i]} onChange={e=>{const next=[...evidence];next[i]=e.target.checked;setEvidence(next)}} className="mt-1"/><span className="text-sm leading-6">{x}</span></label>)}</div><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="rounded-xl bg-slate-50 p-4"><div className="text-sm text-slate-500">{ru?'Коэффициент доказанности':'Evidence score'}</div><div className="mt-1 text-3xl font-bold">{checked*20}%</div><p className="mt-2 text-xs leading-5 text-slate-500">{ru?'Инструмент самопроверки, не рыночная математическая формула.':'A self-check, not a market pricing formula.'}</p></div><div className="rounded-xl bg-slate-50 p-4"><div className="text-sm text-slate-500">{ru?'Разрыв до полной стоимости компании':'Capacity gap'}</div><div className="mt-1 text-3xl font-bold">{money(Math.max(0,metrics.cap-metrics.full),lang)}</div></div></div><div className="mt-6 rounded-xl border border-slate-200 p-5"><h3 className="font-semibold">{ru?'Посчитай дорогую проблему, которую ты решаешь':'Price the problem you solve'}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{ru?'Начинай не с должности и не с навыка. Начинай с проблемы: сколько бизнес теряет без её решения и какую часть этой потери ты реально убираешь.':'Start with the problem, not the job title. Estimate what the business loses without solving it and how much of that loss your work removes.'}</p><label className="mt-4 block text-sm font-semibold">{ru?'Проблема':'Problem'}<input value={problem} onChange={e=>setProblem(e.target.value)} placeholder={ru?'Например: компания теряет продажи из-за низкой конверсии':'For example: the company loses sales because conversion is low'} data-pdf-input className="mt-2 w-full min-h-12 rounded-xl border px-4 py-3 leading-6"/><div data-pdf-value style={{display:'none'}} className="mt-2 min-h-12 rounded-xl border px-4 py-3 leading-6 break-words">{problem||'—'}</div></label><label className="mt-4 block text-sm font-semibold">{ru?'Оценка потерь в месяц':'Estimated monthly loss'}<input data-pdf-input type="number" min="0" value={problemLoss||''} onChange={e=>setProblemLoss(Math.max(0,Number(e.target.value)))} className="mt-2 w-full min-h-12 rounded-xl border px-4 py-3 text-base leading-6"/><div data-pdf-value style={{display:'none'}} className="mt-2 min-h-12 rounded-xl border px-4 py-3 leading-6">{problemLoss?money(problemLoss,lang):'—'}</div></label>{problemLoss>0&&<div className="mt-4 rounded-xl bg-slate-50 p-4"><div className="text-sm text-slate-500">{ru?'Доля потерь, которую покрывает твой текущий экономический эффект':'Share of losses covered by your current impact'}</div><div className="mt-1 text-2xl font-bold">{metrics.problemCoverage}%</div><div className="mt-1 text-xs text-slate-500">{ru?'Это не цена твоей работы. Это контекст стоимости проблемы.':'This is not your price. It is context for the economic value of the problem.'}</div></div>}</div></section>}
function LanguageSwitch({lang,setLang}:{lang:Lang;setLang:(l:Lang)=>void}){return <select aria-label="Language" value={lang} onChange={e=>setLang(e.target.value as Lang)} className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-bold text-slate-700 shadow-sm outline-none focus:border-indigo-500"><option value="ru">RU</option><option value="en">EN</option><option value="kk">KK</option><option value="az">AZ</option></select>}
function Metric({title,value,hint}:{title:string;value:string;hint?:string}){return <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="text-sm font-semibold text-slate-500">{title}</div><div className="mt-2 text-3xl font-bold sm:text-4xl">{value}</div>{hint&&<p className="mt-2 text-xs leading-5 text-slate-500">{hint}</p>}</div>}
function InputSummary({t,salary,contribution,stability,rarity,full,cap,ratio,gap,lang}:{t:any;salary:number;contribution:number;stability:number;rarity:number;full:number;cap:number;ratio:number;gap:number;lang:Lang}){return <section className="mt-6 rounded-2xl border border-slate-200 p-5"><h2 className="text-lg font-bold">{t.inputs}</h2><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><InputItem label={t.salaryInput} value={money(salary,lang)}/><InputItem label={t.contributionInput} value={money(contribution,lang)}/><InputItem label={t.stabilityInput} value={stability.toFixed(1)}/><InputItem label={t.rarityInput} value={rarity.toFixed(1)}/><InputItem label={t.company} value={money(full,lang)}/><InputItem label={t.power} value={money(cap,lang)}/><InputItem label={t.ratioTitle} value={ratio.toFixed(2)}/><InputItem label={t.gap} value={`${gap>=0?'+':''}${money(gap,lang)}`}/></div></section>}
function InputItem({label,value}:{label:string;value:string}){return <div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-500">{label}</div><div className="mt-1 font-semibold">{value}</div></div>}
function SalaryStep({t,value,set,lang}:{t:any;value:number;set:(v:any)=>void;lang:Lang}){return <div><h2 className="text-2xl font-bold">{t.salaryTitle.replace('{currency}',currencyLabel(lang))}</h2><p className="mt-2 text-slate-600">{t.salaryHint}</p><input aria-label={t.salaryTitle.replace('{currency}', currencySymbol(lang))} type="number" min="1" value={value} onChange={e=>set({salary:Math.max(0,Number(e.target.value))})} className="mt-6 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-xl font-semibold text-slate-900 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/><input aria-label={t.salaryTitle.replace('{currency}', currencySymbol(lang))} type="range" min="20000" max="1000000" step="5000" value={Math.min(1000000,Math.max(20000,value))} onChange={e=>set({salary:Number(e.target.value)})} className="mt-5 w-full accent-indigo-600"/><div className="mt-6 rounded-2xl bg-slate-50 p-5 shadow-sm"><div className="text-sm text-slate-500">{t.company}</div><div className="mt-1 text-2xl font-bold">{money(fullCost(value),lang)}</div></div></div>}
function ContributionStep({t,value,set,openModal}:any){return <div><h2 className="text-2xl font-bold">{t.contributionTitle}</h2><p className="mt-2 text-slate-600">{t.contributionHint}</p><p className="mt-3 rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-600">{t.contributionHelp}</p><input aria-label={t.contributionTitle} type="number" min="1" value={value||''} onChange={e=>set({contribution:Math.max(0,Number(e.target.value))})} placeholder="250000" className="mt-6 w-full rounded-xl border px-4 py-3 text-xl"/><p className="mt-3 text-sm text-slate-500">{t.approximate}</p><button onClick={openModal} className="mt-5 rounded-xl border border-slate-300 px-4 py-3 font-semibold">{t.examples}</button></div>}
function SliderStep({title,value,min,max,step,set,low,mid,high}:any){return <div><h2 className="text-2xl font-bold">{title}</h2><div className="mt-8 text-5xl font-bold">{value.toFixed(1)}</div><input aria-label={title} type="range" min={min} max={max} step={step} value={value} onChange={e=>set(Number(e.target.value))} className="mt-6 w-full"/><div className="mt-6 grid gap-3 text-sm text-slate-600"><div>{low}</div><div>{mid}</div><div>{high}</div></div></div>}
function ExampleModal({t,close}:any){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-2xl rounded-2xl bg-white p-5 sm:p-7"><div className="flex justify-between gap-3"><h2 className="text-xl font-bold">{t.modalTitle}</h2><button aria-label={t.close} onClick={close} className="rounded-lg border px-3">×</button></div><p className="mt-2 text-sm leading-6 text-slate-600">{t.modalText}</p><div className="mt-5 grid gap-2 sm:grid-cols-2">{t.professions.map((p:string,i:number)=><div key={p} className="rounded-xl border p-4"><div className="font-semibold">{p}</div><div className="mt-1 text-sm text-slate-600">{t.exampleText[i]}</div></div>)}</div><button onClick={close} className="mt-6 rounded-xl bg-indigo-600 px-5 py-3 font-semibold text-white">{t.close}</button></div></div>}
function AuthModal({t,authMode,setAuthMode,email,setEmail,password,setPassword,authError,authMessage,submitAuth,saving,close}:any){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-2xl bg-white p-6 sm:p-8"><h2 className="text-2xl font-bold">{t.accountTitle}</h2><p className="mt-2 text-sm leading-6 text-slate-600">{t.accountText}</p><div className="mt-6 flex gap-2"><button onClick={()=>setAuthMode('register')} className={`flex-1 rounded-lg px-3 py-2 text-sm font-semibold ${authMode==='register'?'bg-indigo-600 text-white':'border'}`}>{t.register}</button><button onClick={()=>setAuthMode('login')} className={`flex-1 rounded-lg px-3 py-2 text-sm font-semibold ${authMode==='login'?'bg-indigo-600 text-white':'border'}`}>{t.login}</button></div><label className="mt-5 block text-sm font-semibold">{t.email}</label><input aria-label={t.email} type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} className="mt-2 w-full rounded-xl border px-4 py-3"/><label className="mt-4 block text-sm font-semibold">{t.password}</label><input aria-label={t.password} type="password" autoComplete={authMode==='register'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} className="mt-2 w-full rounded-xl border px-4 py-3"/><button onClick={submitAuth} disabled={saving} className="mt-6 w-full rounded-xl bg-indigo-600 px-5 py-3 font-semibold text-white disabled:opacity-50">{saving?t.saving:t.accountButton}</button>{authError&&<p className="mt-3 text-sm text-red-700">{authError}</p>}{authMessage&&<p className="mt-3 text-sm text-slate-600">{authMessage}</p>}<button onClick={close} className="mt-4 w-full text-sm text-slate-500">{t.close}</button></div></div>}
function Verdict({t,kind}:{t:any;kind:'low'|'mid'|'high'}){const title=kind==='low'?t.verdictLow:kind==='mid'?t.verdictMid:t.verdictHigh;const text=kind==='low'?t.verdictLowText:kind==='mid'?t.verdictMidText:t.verdictHighText;const cls=kind==='low'?'bg-emerald-50 text-emerald-800 border-emerald-200':kind==='mid'?'bg-amber-50 text-amber-800 border-amber-200':'bg-red-50 text-red-800 border-red-200';return <div className={`rounded-xl border p-5 ${cls}`}><div className="text-lg font-bold">{title}</div><p className="mt-2 leading-7">{text}</p></div>}
function Diagnostic({t,gap,setGap}:any){return <section data-pdf-section className="mt-6 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-7"><h2 className="text-2xl font-bold">{t.diagnosticTitle}</h2><p className="mt-2 leading-7 text-slate-600">{t.diagnosticText}</p><div className="mt-5 grid gap-3 sm:grid-cols-2">{t.gaps.map((g:any)=><button key={g[0]} onClick={()=>setGap(gap===g[0]?null:g[0])} className={`text-left rounded-xl border p-4 transition ${gap===g[0]?'border-slate-900 bg-slate-50':'border-slate-200 hover:border-slate-400'}`}><div className="text-xs font-bold uppercase tracking-wide text-slate-500">{g[1]}</div><div className="mt-1 font-semibold">{g[2]}</div><p className="mt-2 text-sm leading-6 text-slate-600">{g[3]}</p></button>)}</div>{gap&&<div className="mt-5 rounded-xl bg-slate-50 p-5"><div className="font-semibold">{t.gapActionTitle}</div><p className="mt-2 leading-7 text-slate-700">{t.gapActions[gap]}</p></div>}</section>}

function SkillsChecklist({t,role,setRole,outcome,setOutcome,skills,updateSkill,addSkill,removeSkill,bottleneck}:any){return <section className="mt-6 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><h2 className="text-2xl font-black tracking-tight">{t.skillsTitle}</h2><p className="mt-2 text-sm leading-6 text-slate-600">{t.skillsText}</p><div className="mt-5 grid gap-4 md:grid-cols-2"><label className="block text-sm font-semibold text-slate-800">{t.roleLabel}<input value={role} onChange={e=>setRole(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-base font-semibold outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label><label className="block text-sm font-semibold text-slate-800">{t.outcomeLabel}<input value={outcome} onChange={e=>setOutcome(e.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-base font-semibold outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label></div><div className="mt-6 space-y-4">{skills.map((s:Skill,i:number)=>{const p=s.level*s.criticality;return <div key={i} className="rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="grid gap-3 lg:grid-cols-[2fr_1fr_1fr_1fr]"><label className="block text-sm font-semibold text-slate-800">{t.skillLabel}<input value={s.name} placeholder={t.skillPlaceholder} onChange={e=>updateSkill(i,{name:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label><label className="block text-sm font-semibold text-slate-800">{t.levelLabel}<input aria-label={t.levelLabel} type="number" min="1" max="10" value={s.level} onChange={e=>updateSkill(i,{level:Math.max(1,Math.min(10,Number(e.target.value)))})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label><label className="block text-sm font-semibold text-slate-800">{t.criticalityLabel}<input aria-label={t.criticalityLabel} type="number" min="1" max="10" value={s.criticality} onChange={e=>updateSkill(i,{criticality:Math.max(1,Math.min(10,Number(e.target.value)))})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label><div><div className="text-sm font-semibold text-slate-800">{t.priorityLabel}</div><div className={`mt-2 rounded-xl px-4 py-3 font-bold ${p>=50&&s.level<7?'bg-red-50 text-red-700':'bg-white border border-slate-200'}`}>{p}</div></div></div><label className="mt-3 block text-sm font-semibold text-slate-800">{t.evidenceLabel}<input value={s.evidence} placeholder={t.evidencePlaceholder} onChange={e=>updateSkill(i,{evidence:e.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100"/></label>{skills.length>5&&<button onClick={()=>removeSkill(i)} className="mt-3 text-sm font-semibold text-slate-500 hover:text-red-700">{t.removeSkill}</button>}</div>})}</div><button onClick={addSkill} disabled={skills.length>=7} className="mt-4 rounded-xl border border-slate-300 bg-white px-4 py-2.5 font-semibold text-slate-700 disabled:opacity-50">+ {t.addSkill}</button><p className="mt-4 text-sm leading-6 text-slate-500">{t.skillsHint}</p>{bottleneck&&<div className="mt-6 rounded-2xl bg-indigo-50 p-5"><div className="font-semibold text-indigo-900">{t.bottleneckTitle}</div><div className="mt-2 font-bold">{bottleneck.name}</div><div className="mt-1 text-sm text-slate-600">{t.priorityLabel}: {bottleneck.priority} · {t.levelLabel}: {bottleneck.level}</div></div>}</section>}
